-- OrderSense AI demo seed (generated by scripts/make-demo-data.mjs)
-- Creates demo@ordersense.app / demo1234 with "Al Noor Mini Mart", 28 products,
-- 9 suppliers and 30 days of sales ending today. Safe to re-run.
-- Apply with: supabase db reset   (uses this file automatically)   or paste into the SQL editor.

begin;

-- Demo auth user (local/dev projects). On a hosted project you can instead sign up normally
-- and replace the owner_id below with your user's id.
  raw_app_meta_data, raw_user_meta_data, created_at, updated_at, confirmation_token, recovery_token,
  email_change_token_new, email_change)
values ('00000000-0000-0000-0000-000000000000', '11111111-1111-4111-8111-111111111111', 'authenticated', 'authenticated',
  'demo@ordersense.app', crypt('demo1234', gen_salt('bf')), now(),
  '{"provider":"email","providers":["email"]}', '{}', now(), now(), '', '', '', '')
on conflict (id) do nothing;

values (gen_random_uuid(), '11111111-1111-4111-8111-111111111111', '11111111-1111-4111-8111-111111111111',
  jsonb_build_object('sub', '11111111-1111-4111-8111-111111111111', 'email', 'demo@ordersense.app', 'email_verified', true),
  'email', now(), now(), now())
on conflict (provider_id, provider) do nothing;

delete from public.stores where id = '22222222-2222-4222-8222-222222222222';

values ('22222222-2222-4222-8222-222222222222', '11111111-1111-4111-8111-111111111111', 'Al Noor Mini Mart', 'AED', 'AE', 'en', 2, 10);



on conflict (product_id, sale_date) do update set quantity_sold = excluded.quantity_sold;

values ('22222222-2222-4222-8222-222222222222', 'demo-pos-export.csv', 'processed', 840);

commit;
